// Concept: the phrase that gives them away. The sentence builds large as it is spoken, and
// when the damning words come a single marker stroke runs under them as they are said, one
// unbroken mark from the first word to the last; then the rest of the sentence steps back
// so only the marked words are left in full.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the marker's start is already on screen, a short stroke where the line begins
//   0.3 s  "The auditors signed off": the words rise in as they are said, the hook stroke
//          giving way to the first of them
//   2.3 s  "every single year.": each word rises in and the marker sweeps under it as it is
//          said, joining the one before it with no gap
//   3.8 s  the phrase complete: the other words dim, the marked words hold full
//   to the end: the sentence holds while the camera keeps a slow push
const PHRASE_FROM = 'every'

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function stress(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.emphasis, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// A helper, called directly: one word. A marked word carries its own length of the marker,
// drawn under its lower half and its trailing space, so marked words join into one stroke.
function wordSpan(word, spec) {
  const { frame, fps, unit, colors } = spec
  const enter = arrive(frame, fps, word.atMs, motion.ms.enter)
  const marked = word.atMs >= spec.phraseAt
  // The marker runs across the word while it is said: from its time to the next word's.
  const sweep = marked ? stress(frame, fps, word.atMs, Math.max(motion.ms.micro, word.untilMs - word.atMs)) : 0
  return (
    <span
      key={word.atMs}
      style={{
        position: 'relative', display: 'inline-block', paddingRight: word.last ? 0 : '0.26em', zIndex: 0,
        opacity: enter * (marked ? 1 : 1 - 0.55 * spec.dim),
        transform: 'translateY(' + (1 - enter) * motion.px.rise * unit + 'px)',
      }}
    >
      {marked ? (
        <span
          style={{
            position: 'absolute', left: '-0.06em', bottom: '0.1em', height: '0.4em',
            width: 'calc(' + sweep * 100 + '% + 0.06em)', zIndex: -1,
            backgroundColor: Remotion.withAlpha(colors.accent, 0.75),
          }}
        />
      ) : null}
      {word.text}
    </span>
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080

  const phraseWord = props.words.find((word) => word.text.indexOf(PHRASE_FROM) === 0)
  const phraseAt = phraseWord ? phraseWord.atMs : props.durationMs
  // Each word's window: from its time to the next word's (the last runs motion.ms.reveal).
  const words = props.words.map((word, index) => ({
    ...word,
    untilMs: index + 1 < props.words.length ? props.words[index + 1].atMs : word.atMs + motion.ms.reveal,
    last: index === props.words.length - 1,
  }))
  const lastWord = words[words.length - 1]
  // The rest of the sentence steps back once the phrase is complete, over motion.ms.enter.
  const dim = travel(frame, fps, lastWord.untilMs, motion.ms.enter)
  const hook = arrive(frame, fps, 0, motion.ms.enter)
  const push = travel(frame, fps, 0, props.durationMs)

  const room = width - inset.left - inset.right
  const longest = Math.max(...words.map((word) => word.text.length))
  const size = Math.min((portrait ? 128 : 132) * unit, (0.9 * room) / (Math.max(longest, 8) * 0.55))

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', alignItems: 'flex-start',
        transform: 'scale(' + (1 + 0.03 * push) + ')', transformOrigin: inset.left + 'px 50%',
      }}
    >
      <div style={{ position: 'relative', fontFamily: fonts.heading, fontSize: size, lineHeight: 1.18, color: colors.textPrimary, maxWidth: portrait ? room : room * 0.86 }}>
        <span
          style={{
            // The hook: a short stroke of the marker where the line begins, gone once words arrive.
            position: 'absolute', left: 0, top: size * 0.68, width: 0.5 * size * hook, height: 0.12 * size,
            backgroundColor: colors.accent, opacity: 1 - arrive(frame, fps, words[0].atMs, motion.ms.enter),
          }}
        />
        {words.map((word) => wordSpan(word, { frame, fps, unit, colors, phraseAt, dim }))}
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
